function country(s){return countries.find(c=>c.code===s.person.country)||countries[0]}
function create(seed='LIGNEES',code='random',year=2026){const s={version:1,seed:String(seed),rng:hash(seed),startYear:year,year,generation:1,serial:1,ancestors:[],journal:[],pending:null,market:0,history:[],recession:false};let c;if(code==='random'){let n=rand(s)*countries.reduce((a,c)=>a+c.births,0);c=countries.find(c=>(n-=c.births)<=0)||countries.at(-1)}else c=countries.find(c=>c.code===code)||countries[0];const tier=rand(s);s.person={id:1,name:pick(s,names),surname:pick(s,familyNames[c.code]||familyNames.XX),age:0,country:c.code,origin:c.code,wealthTier:tier,urban:rand(s)<.6,health:85+rand(s)*15,happiness:65,energy:85,stress:10,skill:0,education:0,cash:0,funds:0,speculation:0,home:0,debt:0,salary:0,job:'Enfance',partner:null,children:[],friends:[],parents:[{name:pick(s,names),bond:75},{name:pick(s,names),bond:70}],business:null,focus:'balance',lifestyle:'normal',saving:20,points:3,alive:true,events:[],habits:{sport:false},goal:'liberte',householdIncome:Math.round(c.income*(.2+Math.pow(tier,2)*3)),retired:false,actions:{},moves:0};log(s,`Naissance ${c.name==='Autres pays'?'dans un pays du groupe « autres pays »':`en ${c.name}`}. Votre famille dispose de ${s.person.householdIncome.toLocaleString('fr-FR')} unités de pouvoir d’achat par an.`,true);s.pending=event(s);return s}
function balance(p){return Math.round(p.cash+p.funds+p.speculation+p.home+(p.business?.value||0)-p.debt)}
function income(s){const p=s.person;return Math.round(p.salary+(p.business?.profit||0)+(p.retired?country(s).income*.35:0))}
