function partner(s){return{name:pick(s,names),age:Math.max(18,s.person.age+Math.floor(rand(s)*7)-3),bond:65,alive:true}}
function child(s,adopt=false){const p=s.person;const x={id:++s.serial,name:pick(s,names),surname:p.surname,age:adopt?3:0,born:s.year-(adopt?3:0),bond:70,skill:0,health:90,alive:true,ambition:pick(s,['créer','explorer','aider','bâtir une famille','apprendre']),cash:0,education:0};p.children.push(x);p.happiness+=8;log(s,`${x.name} rejoint votre famille. Une nouvelle histoire commence.`,true);return x}
function apply(s,f){const p=s.person;for(const[k,key]of Object.entries({health:'health',happy:'happiness',energy:'energy',stress:'stress',skill:'skill'}))if(f[k])p[key]=clamp(p[key]+f[k]);if(f.cash){if(f.cash<0)spend(s,-f.cash);else p.cash+=f.cash}if(f.salary)p.salary=Math.round(p.salary*f.salary);if(f.bond&&p.partner)p.partner.bond=clamp(p.partner.bond+f.bond);if(f.parents)p.parents.forEach(x=>x.bond=clamp(x.bond+f.parents));if(f.childbond)p.children.forEach(x=>x.bond=clamp(x.bond+f.childbond));if(f.childskill)p.children.forEach(x=>x.skill+=f.childskill);if(f.friend)p.friends.push({name:pick(s,names),bond:55,age:p.age});if(f.study){p.education+=f.study;p.skill=clamp(p.skill+f.study*9);p.job='En formation'}if(f.tuition){const family=p.householdIncome>country(s).income?f.tuition*.8:f.tuition*.2;p.debt+=Math.max(0,f.tuition-family)}if(f.job)findJob(s);if(f.retire){p.retired=true;p.salary=0;p.job='Retraite'}if(f.adopt){if(p.age>=21){spend(s,country(s).income*.2);child(s,true)}}if(f.bizGrow&&p.business){p.business.value*=f.bizGrow;p.business.profit*=f.bizGrow}if(f.roll)roll(s,f.roll)}
function spend(s,n){const p=s.person;if(p.cash>=n)p.cash-=n;else{p.debt+=n-p.cash;p.cash=0}}
function findJob(s){const p=s.person,c=country(s);const chance=clamp(55+p.skill*.45+p.education*8,20,96)/100;if(rand(s)<chance){p.salary=Math.round(c.income*(.45+p.education*.22+p.skill*.014)*(.8+rand(s)*.4));p.job=p.education>=2?pick(s,['Ingénierie','Design & création','Santé & recherche','Gestion de projets','Enseignement']):pick(s,['Commerce','Artisanat','Services','Logistique','Administration']);log(s,`Vous trouvez un emploi : ${p.job.toLowerCase()}. Revenu annuel brut simulé : ${p.salary.toLocaleString('fr-FR')} UPA.`,true)}else{p.job='Sans emploi';p.salary=0;log(s,'La recherche d’emploi n’aboutit pas cette fois. Vous pourrez réessayer.')}}
function roll(s,type){const p=s.person,c=country(s),r=rand(s);if(type==='promotion'){const prob=clamp(30+p.skill*.6+p.education*5,10,90)/100;if(r<prob){p.salary=Math.round(Math.max(p.salary,c.income*.5)*1.28);p.stress=clamp(p.stress+9);log(s,'Votre candidature est retenue. Vos responsabilités et votre salaire augmentent.',true)}else{p.happiness=clamp(p.happiness-4);log(s,'Le poste revient à une autre personne. Votre préparation pourra servir ailleurs.')}}if(type==='partner'){if(r<.65){p.partner=partner(s);log(s,`Une relation commence avec ${p.partner.name}.`,true)}else log(s,'La rencontre ne devient pas une relation. Vous avez malgré tout osé.')}if(type==='child'){const chance=p.age<32?.65:p.age<38?.5:p.age<43?.3:.15;if(r<chance)child(s);else log(s,'Votre projet parental n’aboutit pas cette année. Vous pouvez poursuivre ou envisager une autre voie.')}if(type==='sector'){if(r<(.3-p.skill*.002)){p.salary=0;p.job='Sans emploi';log(s,'Votre poste disparaît. Votre expérience reste un atout pour la suite.',true)}else{p.salary*=1.05;log(s,'Votre expérience vous permet de traverser la transition.')}}if(type==='pitch'){const stake=p.cash*.05;p.cash-=stake;const gain=r<.60?0:r<.9?stake*1.4:stake*4;p.cash+=gain;log(s,gain===0?'Le placement échoue. La somme engagée est perdue.':`Le placement rapporte ${Math.round(gain-stake).toLocaleString('fr-FR')} UPA. Ce résultat ne garantit rien pour la prochaine fois.`)}if(type==='expand'){spend(s,c.income*.05);if(r<.45+p.skill*.003){p.business.profit*=1.35;p.business.value*=1.2;log(s,'Le nouveau marché répond présent. Votre activité progresse.',true)}else log(s,'Le test commercial ne trouve pas son public. La perte reste limitée au budget engagé.')}}
function choose(s,index){if(!s.pending||!s.person.alive)return false;const e=s.pending,ch=e.choices[index];if(!ch)return false;log(s,`${e.title} — ${ch.label}`,true);s.person.events.push(e.id);s.pending=null;apply(s,ch.fx);if(ch.fx.advance){for(let i=0;i<ch.fx.advance&&s.person.alive;i++)year(s,false);if(s.person.alive&&s.person.job==='En formation'&&s.person.age>=20)findJob(s);if(s.person.alive)s.pending=event(s)}return true}
function ageAncestors(s){for(const a of s.ancestors){if(!a.alive)continue;a.age++;a.children.forEach(x=>{if(x.id===s.person.id){x.age=s.person.age;x.health=s.person.health}else x.age++});a.health=clamp(a.health-(a.age>55?1.2:.3));const rate=a.age<65?.002:a.age<80?.015:.04*Math.exp((a.age-80)/9);if(a.age>110||rand(s)<rate){a.alive=false;const estate=Math.max(0,balance(a)),share=estate*(a.partner?.5:1)/Math.max(1,a.children.filter(x=>x.alive).length);for(const x of a.children){if(!x.alive)continue;x.cash+=share;if(x.id===s.person.id){s.person.cash+=share;log(s,`${a.name}, votre parent, s’éteint à ${a.age} ans. Vous recevez ${Math.round(share).toLocaleString('fr-FR')} UPA de succession.`,true)}}}}}
function year(s,withEvent=true){const p=s.person;if(!p.alive||s.pending)return false;p.age++;s.year++;ageAncestors(s);p.points=3;p.actions={};const c=country(s);const shock=rand(s);s.recession=shock<.09;s.market=s.recession?-.18-rand(s)*.16:(rand(s)-.33)*.25;p.funds=Math.max(0,p.funds*(1+s.market));p.speculation=Math.max(0,p.speculation*(1+(rand(s)-.51)*1.2));if(p.home)p.home*=Math.max(.75,1+s.market*.35+(rand(s)-.5)*.06);if(p.business){const factor=s.recession?.65:.85+rand(s)*.4;p.business.profit*=factor;p.business.value=Math.max(0,p.business.value*(.85+rand(s)*.28));if(rand(s)<.025){log(s,'Votre entreprise ne peut plus poursuivre son activité. Sa valeur est perdue.',true);p.business=null}}if(p.age>=18){const earn=income(s);let surplus=earn-costs(s);if(p.debt>0){const interest=p.debt*.045;surplus-=interest;const payment=Math.min(p.debt,Math.max(0,surplus*.2));p.debt-=payment;surplus-=payment}if(surplus>=0){const saved=surplus*p.saving/100;p.funds+=saved;p.cash+=surplus-saved}else spend(s,-surplus);if(p.home)spend(s,p.home*.012);if(p.salary>0)p.salary*=1.015+(p.focus==='career'?.035:0);if(p.focus==='career'){p.skill=clamp(p.skill+2);p.stress=clamp(p.stress+4);p.energy=clamp(p.energy-3)}else if(p.focus==='family'){p.happiness=clamp(p.happiness+2);if(p.partner)p.partner.bond=clamp(p.partner.bond+3);p.children.forEach(x=>x.bond=clamp(x.bond+2))}else if(p.focus==='health'){p.health=clamp(p.health+3);p.stress=clamp(p.stress-3)}else{p.stress=clamp(p.stress-2);p.energy=clamp(p.energy+3)}}p.health=clamp(p.health-(p.age>55?1.0:p.age>35?.35:.08)-(p.stress>75?1:0)+(p.habits.sport?.8:0));p.happiness=clamp(p.happiness+(p.cash<0?-2:0)-(p.stress>70?2:0)+(p.partner?.3:-.1));p.energy=clamp(p.energy+5-p.stress*.04);if(p.partner){p.partner.age++;p.partner.bond=clamp(p.partner.bond-1);if(p.partner.bond<25&&rand(s)<.25){log(s,`${p.partner.name} et vous vous séparez. Le partage du foyer coûte une partie de vos liquidités.`,true);p.cash*=.8;p.partner=null}}p.children.forEach(x=>{x.age++;x.skill=clamp(x.skill+1+p.education*.3+(p.focus==='family'?1:0));if(x.age===18){x.education=rand(s)<clamp(.25+p.education*.15+p.wealthTier*.2,.1,.95)?2:1;log(s,`${x.name} atteint l’âge adulte et souhaite ${x.ambition}.`,true)}if(x.age>=18)x.cash+=c.income*(.08+x.education*.05)});p.friends.forEach(x=>{x.age++;x.bond=clamp(x.bond-1)});let death=p.age<5?.002:p.age<45?.0005:p.age<65?.003:p.age<80?.013:.04*Math.exp((p.age-80)/9);death*=Math.exp((77-c.life)*.035)*(1+(100-p.health)/90);if(p.age>110||rand(s)<death){p.alive=false;s.pending=null;log(s,`${p.name} s’éteint à ${p.age} ans. Son histoire reste dans votre lignée.`,true)}if(s.recession&&p.age>=18)log(s,'Une récession touche le monde. Les marchés et les entreprises en ressentent les effets.');s.history.push({year:s.year,value:balance(p)});if(s.history.length>150)s.history.shift();if(withEvent&&p.alive)s.pending=event(s);return true}
function action(s,type,value){const p=s.person,c=country(s);if(!p.alive)return{ok:false,message:'Cette vie est terminée.'};const adult=['job','date','child','adopt','business','home','migrate','invest','withdraw','repay','sellhome','sellbusiness','breakup'];if(adult.includes(type)&&p.age<18)return{ok:false,message:'Cette action devient disponible à 18 ans.'};const free=['focus','saving','lifestyle','invest','withdraw','repay'];if(!free.includes(type)&&p.points<=0)return{ok:false,message:'Votre temps disponible est épuisé pour cette année.'};let msg='';
if(type==='focus'){if(!['balance','career','family','health'].includes(value))return{ok:false};p.focus=value;msg='Votre priorité est mise à jour.'}
else if(type==='saving'){p.saving=clamp(Number(value),0,80);msg='Votre épargne automatique est ajustée.'}
else if(type==='lifestyle'){if(!['normal','frugal','comfort'].includes(value))return{ok:false};p.lifestyle=value;msg='Votre niveau de vie est ajusté.'}
else if(type==='invest'){const n=Number(value.amount);if(!Number.isFinite(n)||n<=0||n>p.cash||!['funds','speculation'].includes(value.asset))return{ok:false,message:'Montant invalide ou liquidités insuffisantes.'};p.cash-=n;p[value.asset]+=n;msg='Investissement effectué.'}
else if(type==='withdraw'){const n=Number(value.amount);if(!Number.isFinite(n)||n<=0||!['funds','speculation'].includes(value.asset)||n>p[value.asset])return{ok:false,message:'Montant supérieur à votre position.'};p[value.asset]-=n;p.cash+=n;msg='Vente effectuée à la valeur actuelle.'}
else if(type==='repay'){const n=Math.min(p.cash,p.debt);if(n<=0)return{ok:false,message:'Aucune dette remboursable.'};p.cash-=n;p.debt-=n;msg='Dette remboursée avec vos liquidités.'}
else if(type==='learn'){p.skill=clamp(p.skill+5);p.energy=clamp(p.energy-5);msg='Vous progressez dans votre apprentissage.'}
else if(type==='rest'){p.energy=clamp(p.energy+15);p.stress=clamp(p.stress-10);p.health=clamp(p.health+2);msg='Vous prenez du temps pour souffler.'}
else if(type==='sport'){p.health=clamp(p.health+4);p.stress=clamp(p.stress-4);p.habits.sport=true;msg='Une habitude sportive s’installe.'}
else if(type==='social'){p.happiness=clamp(p.happiness+6);if(p.partner)p.partner.bond=clamp(p.partner.bond+7);p.children.forEach(x=>x.bond=clamp(x.bond+5));if(rand(s)<.35)p.friends.push({name:pick(s,names),bond:60,age:p.age});msg='Vous consacrez du temps aux personnes qui comptent.'}
else if(type==='job'){findJob(s);msg=p.salary?'Un nouveau chapitre professionnel.':'La recherche continue.'}
else if(type==='date'){if(p.partner)return{ok:false,message:'Vous êtes déjà en couple.'};roll(s,'partner');msg=p.partner?'Une relation commence.':'Pas de relation cette fois.'}
else if(type==='child'){if(!p.partner||p.age<21||p.age>45||p.children.length>=5)return{ok:false,message:'Projet disponible en couple, entre 21 et 45 ans, jusqu’à 5 enfants.'};roll(s,'child');msg='Votre projet parental avance.'}
else if(type==='adopt'){if(p.age<25||p.age>60||p.children.length>=5||p.cash<c.income*.2)return{ok:false,message:'Adoption : 25 à 60 ans, moins de 5 enfants, et budget disponible de 20 % du revenu de référence.'};p.cash-=c.income*.2;child(s,true);msg='Votre famille s’agrandit.'}
else if(type==='business'){if(p.business)return{ok:false,message:'Vous dirigez déjà une activité.'};const cost=c.income*.2;if(p.cash<cost)return{ok:false,message:'Capital nécessaire : '+Math.round(cost)+' UPA.'};p.cash-=cost;const success=rand(s)<clamp(.25+p.skill*.006+p.education*.04,.15,.85);p.business={value:cost*(success?2:0.5),profit:c.income*(success?.35:.04),name:'Mon activité'};p.stress=clamp(p.stress+12);msg=success?'Votre activité trouve ses premiers clients.':'Le démarrage est difficile, les revenus sont faibles.'}
else if(type==='home'){if(p.home)return{ok:false,message:'Vous possédez déjà un logement.'};const price=c.income*5,deposit=price*.2;if(p.cash<deposit||income(s)<c.income*.65)return{ok:false,message:'Achat : apport de '+Math.round(deposit)+' UPA et revenu minimum de '+Math.round(c.income*.65)+' UPA/an.'};p.cash-=deposit;p.home=price;p.debt+=price-deposit;msg='Vous devenez propriétaire avec un crédit.'}
else if(type==='sellhome'){if(!p.home)return{ok:false,message:'Aucun logement à vendre.'};p.cash+=p.home*.94;p.home=0;const n=Math.min(p.debt,p.cash);p.debt-=n;p.cash-=n;msg='Logement vendu, frais de 6 % et dette remboursée dans la limite du prix.'}
else if(type==='sellbusiness'){if(!p.business)return{ok:false,message:'Aucune activité à céder.'};p.cash+=p.business.value*.85;p.business=null;msg='Votre entreprise est cédée (15 % de frais et décote).'}
else if(type==='breakup'){if(!p.partner)return{ok:false,message:'Vous n’êtes pas en couple.'};p.partner=null;p.cash*=.85;p.happiness=clamp(p.happiness-8);msg='Votre couple se sépare. Une nouvelle période commence.'}
else if(type==='migrate'){const dest=countries.find(x=>x.code===value);if(!dest||dest.code===p.country)return{ok:false,message:'Choisissez un autre pays.'};const cost=Math.max(c.income*.25,dest.income*.12);if(p.cash<cost)return{ok:false,message:'Budget nécessaire : '+Math.round(cost)+' UPA.'};p.cash-=cost;const chance=clamp(.2+p.education*.12+p.skill*.004,.15,.85);if(rand(s)<chance){p.country=dest.code;p.moves++;p.salary=0;p.job='Sans emploi';p.stress=clamp(p.stress+12);msg='Votre projet de migration aboutit. Vous cherchez maintenant un emploi sur place.'}else msg='Votre démarche n’aboutit pas. Le budget engagé couvre les frais et préparatifs.'}
else return{ok:false,message:'Action inconnue.'};if(!free.includes(type))p.points--;log(s,msg);return{ok:true,message:msg}}
function inherit(s,id){const old=s.person,x=old.children.find(x=>x.id===id);if(!x||!x.alive)return false;const original=JSON.parse(JSON.stringify(old));const aliveChildren=old.children.filter(x=>x.alive);let share=0;if(!old.alive){const assets=Math.max(0,balance(old));share=assets*(old.partner?.5:1)/aliveChildren.length}const past=s.ancestors.find(x=>x.id===old.id);if(past)Object.assign(past,original);else s.ancestors.push(original);s.generation++;s.person={...original,id:x.id,name:x.name,surname:x.surname,age:x.age,health:x.health,happiness:65,energy:85,stress:20,skill:x.skill,education:x.education,cash:x.cash+share,funds:0,speculation:0,home:0,debt:0,job:x.age<18?'Enfance':'Sans emploi',salary:0,partner:null,children:[],friends:[],parents:[{name:old.name,bond:x.bond}],business:null,points:3,events:[],alive:true,retired:false,actions:{},householdIncome:Math.max(country(s).income*.3,income(s)),habits:{sport:false},focus:'balance',moves:0};s.pending=null;if(s.person.age>=18)findJob(s);log(s,`Vous incarnez maintenant ${x.name}, ${x.age} ans. ${old.alive?'Votre parent poursuit sa vie en arrière-plan.':`Héritage reçu : ${Math.round(share).toLocaleString('fr-FR')} UPA.`}`,true);s.pending=event(s);return true}
root.Life={countries,create,rand,choose,year,action,inherit,balance,income,costs,country,event,log,clamp};if(typeof module!=='undefined')module.exports=root.Life;
